// ─── Cuentas a vigilar ────────────────────────────────────────────────────
// Instagram usa Business Discovery: devuelve datos PÚBLICOS de otras cuentas
// Business o Creator con el mismo token que ya usas. No funciona con perfiles
// personales ni con cuentas privadas.
//
// YouTube usa el handle público del canal; no hace falta permiso especial.
const CUENTAS = [
  { handle: 'growthopsdaily',  platform: 'instagram', focus: 'Operaciones de agencia' },
  { handle: 'b2bfunnelguy',    platform: 'instagram', focus: 'Embudos y CRO' },
  { handle: 'offerarchitect',  platform: 'instagram', focus: 'Diseño de oferta' },
  { handle: '@salesdmpro',     platform: 'youtube',   focus: 'Prospección por DM' },
];

const AJUSTES = {
  IG_USER_ID: 'PON_AQUI_TU_IG_USER_ID',
  GRAPH_API_VERSION: 'v25.0',
  GRAPH_API_HOST: 'https://graph.facebook.com',
  YT_DATA_HOST: 'https://www.googleapis.com',
};

const env = (() => { try { return $env ?? {}; } catch { return {}; } })();
const IG_USER_ID = env.IG_USER_ID || AJUSTES.IG_USER_ID;
const VERSION = env.GRAPH_API_VERSION || AJUSTES.GRAPH_API_VERSION;
const GRAPH_HOST = env.GRAPH_API_HOST || AJUSTES.GRAPH_API_HOST;
const YT_HOST = env.YT_DATA_HOST || AJUSTES.YT_DATA_HOST;

// Una llamada por cuenta; cada una lleva a dónde ir según su plataforma.
return CUENTAS.map((c) => ({
  json: {
    ...c,
    url: c.platform === 'instagram'
      ? `${GRAPH_HOST}/${VERSION}/${IG_USER_ID}?fields=business_discovery.username(${c.handle})`
        + '%7Busername%2Cname%2Cfollowers_count%2Cmedia_count%2Cprofile_picture_url'
        + '%2Cmedia.limit(12)%7Blike_count%2Ccomments_count%2Ctimestamp%7D%7D'
      : `${YT_HOST}/youtube/v3/channels?part=snippet,statistics&forHandle=${encodeURIComponent(c.handle)}`,
  },
}));

// Normaliza cuentas de Instagram y de YouTube a una misma fila de tabla.
const cuentas = $('Cuentas').all().map((i) => i.json);
const respuestas = $input.all();

const miles = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const fmt = (n) => (n == null ? null
  : n >= 1e6 ? (n / 1e6).toFixed(1) + 'M'
  : n >= 1e3 ? (n / 1e3).toFixed(1) + 'K'
  : String(n));

const avisos = [];

const rows = cuentas.map((cuenta, i) => {
  const body = respuestas[i]?.json ?? {};
  const base = { id: cuenta.handle, handle: cuenta.handle, platform: cuenta.platform, focus: cuenta.focus };

  if (cuenta.platform === 'instagram') {
    const d = body.business_discovery;
    if (!d) {
      // Business Discovery falla con perfiles personales y cuentas privadas.
      avisos.push(`${cuenta.handle}: ${body.error?.message ?? 'sin datos'}`);
      return { ...base, handle: '@' + cuenta.handle, followers: null, engagement: null, cadence: null, posts: null };
    }

    const media = d.media?.data ?? [];
    const interacciones = media.reduce((s, m) => s + (m.like_count ?? 0) + (m.comments_count ?? 0), 0);
    // Sin alcance público, el engagement se calcula sobre seguidores, que es lo
    // que se puede ver desde fuera. No es el mismo número que da su panel.
    const engagement = media.length && d.followers_count
      ? Math.round((interacciones / media.length / d.followers_count) * 1000) / 10
      : null;

    // Cadencia: publicaciones por semana según las fechas de las últimas piezas.
    const fechas = media.map((m) => new Date(m.timestamp)).filter((x) => !Number.isNaN(x.getTime()));
    let cadence = null;
    if (fechas.length > 1) {
      const dias = (Math.max(...fechas) - Math.min(...fechas)) / 86400000;
      if (dias > 0) cadence = (Math.round((fechas.length / dias) * 7 * 10) / 10) + '/semana';
    }

    return { ...base,
      handle: '@' + (d.username ?? cuenta.handle),
      name: d.name ?? null,
      followers: d.followers_count != null ? fmt(d.followers_count) : null,
      followersRaw: d.followers_count ?? null,
      posts: d.media_count != null ? miles(d.media_count) : null,
      engagement, cadence };
  }

  const canal = body.items?.[0];
  if (!canal) {
    avisos.push(`${cuenta.handle}: ${body.error?.message ?? 'canal no encontrado'}`);
    return { ...base, followers: null, engagement: null, cadence: null, posts: null };
  }

  const st = canal.statistics ?? {};
  const subs = Number(st.subscriberCount);
  const vistas = Number(st.viewCount);
  const videos = Number(st.videoCount);

  return { ...base,
    handle: canal.snippet?.customUrl ?? cuenta.handle,
    name: canal.snippet?.title ?? null,
    followers: Number.isFinite(subs) ? fmt(subs) : null,
    followersRaw: Number.isFinite(subs) ? subs : null,
    posts: Number.isFinite(videos) ? miles(videos) : null,
    // En YouTube lo comparable no es el engagement sino las vistas por vídeo.
    viewsPerVideo: Number.isFinite(vistas) && videos ? fmt(Math.round(vistas / videos)) : null,
    engagement: null, cadence: null };
});

rows.sort((a, b) => (b.followersRaw ?? -1) - (a.followersRaw ?? -1));

return [{ json: { source: 'api', errors: avisos, items: rows } }];
